  it('computes only closed callable utility projections', () => {
    const closed = lower(
      'callable-utilities.ts',
      `function project(value: number, flag?: boolean): string { return ''; }
       export type ProjectedReturn = ReturnType<typeof project>;
       export type ProjectedParameters = Parameters<typeof project>;`,
    ).module;
    const emitted = emitIrModuleCpp(closed, { runtimeProfile: 'flight-cpp' }).contents;

    expect(emitted).toContain('using ProjectedReturn = flight::String;');
    expect(emitted).toContain('using ProjectedParameters = std::tuple<double, std::optional<bool>>;');

    const generic = lower(
      'generic-parameters.ts',
      'export type GenericParameters<T extends (value: number) => number> = Parameters<T>;',
    ).module;
    expect(() => emitIrModuleCpp(generic, { runtimeProfile: 'flight-cpp' })).toThrow(
      'Parameters<T> requires a statically resolvable non-generic callable type',
    );

    const genericReturn = lower(
      'generic-return.ts',
      'export type GenericReturn = ReturnType<<T>(value: T) => T>;',
    ).module;
    expect(() => emitIrModuleCpp(genericReturn, { runtimeProfile: 'flight-cpp' })).toThrow(
      'ReturnType<T> requires a statically resolvable non-generic callable type',
    );

    // `unknown` has a representation now, so a callable returning it resolves rather than being
    // refused for lacking one.
    const unknownReturn = lower('unknown-return.ts', 'export type UnknownReturn = ReturnType<() => unknown>;').module;
    expect(emitIrModuleCpp(unknownReturn, { runtimeProfile: 'flight-cpp' }).contents).toContain(
      'using UnknownReturn = flight::Any;',
    );

    // A position with nothing to deduce from is erased; a const whose initializer already states the
    // type keeps the deduction, so `grid.length` stays a number rather than becoming a value of no
    // stated type.
    const deduced = lower(
      'deduced-unknown.ts',
      `export function lengths(grid: readonly (readonly number[])[]): number {
  const rows = grid.length;
  let mutable = grid.length;
  mutable = rows;
  return rows + mutable;
}`,
    ).module;
    const deducedOutput = emitIrModuleCpp(deduced, { runtimeProfile: 'flight-cpp' }).contents;
    // The member read's type is recorded now, so the local states it rather than deducing it from the
    // initializer. `auto` was the fallback for a type nobody had recorded, not the contract.
    expect(deducedOutput).toContain('double rows = ');
    expect(deducedOutput).not.toContain('flight::Any rows');
    // The mutable binding keeps its stated type too, which is the whole point: the erased value was
    // never the right answer here, it was the fallback for a type that had not been recorded.
    expect(deducedOutput).toContain('double mutable_ = ');
    expect(deducedOutput).not.toContain('flight::Any mutable_');

    // Asserting an erased value to a primitive reads the alternative rather than casting to it: the
    // erased value has no conversion operator, so `static_cast` does not compile.
    const asserted = lower(
      'asserted-unknown.ts',
      `export function asText(input: unknown): string { return input as string; }
       export function asCount(input: unknown): number { return input as number; }`,
    ).module;
    const assertedOutput = emitIrModuleCpp(asserted, { runtimeProfile: 'flight-cpp' }).contents;
    expect(assertedOutput).toContain('input.as_string()');
    expect(assertedOutput).toContain('input.as_number()');
    expect(assertedOutput).not.toContain('static_cast<flight::String>(input)');

    const rest = lower(
      'rest-parameters.ts',
      'export type RestParameters = Parameters<(...values: number[]) => void>;',
    ).module;
    expect(() => emitIrModuleCpp(rest, { runtimeProfile: 'flight-cpp' })).toThrow(
      'Parameters<T> with rest parameters requires variadic C++ tuple lowering',
    );

    const restReturn = lower(
      'rest-return.ts',
      'export type RestReturn = ReturnType<(...values: number[]) => number>;',
    ).module;
    expect(() => emitIrModuleCpp(restReturn, { runtimeProfile: 'flight-cpp' })).toThrow(
      'ReturnType<T> with rest parameters is outside closed callable projection lowering',
    );

    const timer = lower('timer-return.ts', 'export type Timer = ReturnType<typeof setTimeout>;').module;
    expect(() => emitIrModuleCpp(timer, { runtimeProfile: 'flight-cpp' })).toThrow('missing: setTimeout[value]');
    const timerBinding = {
      bindings: [
        {
          callResultType: 'host::TimerHandle',
          headers: ['host/timer.hpp'],
          nullability: 'non-null' as const,
          ownership: 'value' as const,
          sourceName: 'setTimeout',
          space: 'value' as const,
          targetName: 'host::set_timeout',
        },
      ],
      schema: 'flight-cpp-external-bindings/1' as const,
    };
    const emittedTimer = emitIrModuleCpp(timer, {
      externalBindings: timerBinding,
      runtimeProfile: 'flight-cpp',
    }).contents;
    expect(emittedTimer).toContain('#include <host/timer.hpp>');
    expect(emittedTimer).toContain('using Timer = host::TimerHandle;');

    const timerWithoutResult = {
      ...timerBinding,
      bindings: timerBinding.bindings.map(({ callResultType: _, ...binding }) => binding),
    };
    expect(() =>
      emitIrModuleCpp(timer, { externalBindings: timerWithoutResult, runtimeProfile: 'flight-cpp' }),
    ).toThrow('ReturnType<T> requires a statically resolvable non-generic callable type');

    const timerParameters = lower(
      'timer-parameters.ts',
      'export type TimerParameters = Parameters<typeof setTimeout>;',
    ).module;
    expect(() =>
      emitIrModuleCpp(timerParameters, { externalBindings: timerBinding, runtimeProfile: 'flight-cpp' }),
    ).toThrow('Parameters<T> requires a statically resolvable non-generic callable type');

    const runtimeViews = lower(
      'runtime-views.ts',
      'export type RuntimeViews = ArrayLike<number> | ArrayBufferLike;',
    ).module;
    expect(() => emitIrModuleCpp(runtimeViews, { runtimeProfile: 'flight-cpp' })).toThrow(
      'missing: ArrayBufferLike[type], ArrayLike[type]',
    );
  });

  it('emits dependent Parameters<T> as constrained forwarding packs and refuses value use', () => {
    const module = lower(
      'dependent-callable-pack.ts',
      `export function forward<T extends (...values: any[]) => void>(slot: T, ...args: Parameters<T>): void {
         slot(...args);
       }
       export function wrap<T extends (...values: any[]) => void>(slot: T): T {
         return ((...args: Parameters<T>): void => slot(...args)) as unknown as T;
       }
       export function wrapErased<T extends (...values: any[]) => void>(slot: T): T {
         return ((...args: any[]): void => slot(...args)) as unknown as T;
       }`,
    ).module;
    const emitted = emitIrModuleCpp(module, { runtimeProfile: 'flight-cpp' }).contents;

    expect(emitted).toContain('template <typename T, typename... ArgsPack>');
    expect(emitted).toContain('requires flight::callable_signature_v1<T>::template accepts<ArgsPack...>');
    expect(emitted).toContain('inline void forward(T slot, ArgsPack&&... args)');
    expect(emitted).toContain('ArgsPack&&... args');
    expect(emitted).toContain('slot(std::forward<ArgsPack>(args)...);');
    expect(emitted).toContain('flight::bind_callable_v1<T>(');
    expect(emitted).toContain('inline T wrap(T slot)');
    expect(emitted).toContain('[=]<typename... ArgsPack>');
    expect(emitted).not.toContain('flight::Array<auto>');

    const valueUse = lower(
      'dependent-callable-pack-value.ts',
      `export function count<T extends (...values: any[]) => void>(...args: Parameters<T>): number {
         return args.length;
       }`,
    ).module;
    expect(() => emitIrModuleCpp(valueUse, { runtimeProfile: 'flight-cpp' })).toThrow(
      'dependent callable parameter pack args may only be used as a terminal call spread',
    );
  });

