  it('projects the pinned XML trim call from its short-circuit-proven String payload', () => {
    const types = ts.createSourceFile(
      '/flight/packages/types/src/contract.ts',
      `export interface XmlElement {
         attributes: Record<string, string>;
         children: XmlElement[];
         content: Array<string | XmlElement>;
         name: string;
         text: string;
       }`,
      ts.ScriptTarget.Latest,
      true,
    );
    const xmlQuery = ts.createSourceFile(
      '/flight/packages/xml/src/xmlQuery.ts',
      `import type { XmlElement } from '@flighthq/types/contract';
       export function getXmlElementAttribute(element: Readonly<XmlElement>, name: string): string | null {
         const value = element.attributes[name];
         return value !== undefined ? value : null;
       }
       export function getXmlElementAttributeNumber(
         element: Readonly<XmlElement>,
         name: string,
       ): number | null {
         const value = element.attributes[name];
         if (value === undefined || value.trim() === '') return null;
         const parsed = Number(value);
         return Number.isFinite(parsed) ? parsed : null;
       }
       export function getXmlElementChildByName(
         element: Readonly<XmlElement>,
         name: string,
       ): XmlElement | null {
         for (const child of element.children) {
           if (child.name === name) return child;
         }
         return null;
       }
       export function getXmlElementChildrenByName(
         element: Readonly<XmlElement>,
         name: string,
       ): XmlElement[] {
         return element.children.filter((child) => child.name === name);
       }`,
      ts.ScriptTarget.Latest,
      true,
    );
    const moduleResolution: CompilerModuleResolutionPlan = {
      edges: [
        {
          specifier: '@flighthq/types/contract',
          target: { packageName: '@flighthq/types', source: 'packages/types/src/contract.ts' },
        },
      ],
      schema: 'flight-compiler-module-resolution/1',
    };
    const modules = lowerTypeScriptSources(
      [
        { packageName: '@flighthq/types', sourceFile: types, upstreamDirectory: '/flight' },
        { packageName: '@flighthq/xml', sourceFile: xmlQuery, upstreamDirectory: '/flight' },
      ],
      moduleResolution,
    ).map((result) => result.module);
    const query = modules[1]!.declarations.find(
      (declaration) => declaration.kind === 'function' && declaration.binding.name === 'getXmlElementAttributeNumber',
    );
    const guard = query?.kind === 'function' ? query.body[1] : undefined;
    const trim =
      guard?.kind === 'if' && guard.condition.kind === 'binary' && guard.condition.right.kind === 'binary'
        ? guard.condition.right.left
        : undefined;
    const receiver = trim?.kind === 'call' && trim.callee.kind === 'property' ? trim.callee.object : undefined;

    expect(receiver).toMatchObject({
      kind: 'identifier',
      presence: 'narrowedPresent',
      reference: { binding: { name: 'value' } },
    });

    const emitted = createCppCompilerBackend().createEmissionSession!({
      moduleResolution,
      modules,
      options: {
        packageTargets: {
          '@flighthq/types': { includePrefix: 'flight/types', namespace: 'flight::types' },
          '@flighthq/xml': { includePrefix: 'flight/xml', namespace: 'flight::xml' },
        },
        runtimeProfile: 'flight-cpp',
      },
    }).emitModule(modules[1]!)[0]!.contents;

    expect(emitted).toContain(
      'const std::optional<flight::String> value = flight::row_get<flight::RowKey<"attributes">>(element).get(name);',
    );
    expect(emitted).toContain('value.value().trim()');
    expect(emitted).not.toContain('value.trim()');
  });

  it('refuses member projection from absent or heterogeneous indexed storage', () => {
    const refusal = (source: string) =>
      captureBackendEmissionFailure(() =>
        emitIrModuleCpp(lower('optional-member-projection.ts', source).module, { runtimeProfile: 'flight-cpp' }),
      );

    expect(
      refusal(
        `export function read(values: Readonly<Record<string, string>>, key: string): string {
           const value = values[key];
           const missing = value === undefined;
           return value.trim();
         }`,
      ).rule,
    ).toBe('cpp-member-projection-without-present-storage');
    expect(
      refusal(
        `export function read(values: Readonly<Record<string, string[] | number[]>>, key: string): number {
           const value = values[key];
           if (value === undefined || value.length === 0) return 0;
           return value.length;
         }`,
      ).rule,
    ).toBe('cpp-member-projection-multiple-present-domains');
  });

  // The boundary the absence-storage decision runs on, pinned from both sides.
  //
  // The receiver the semantic layer records for `Readonly<Record<string, string>>` reads `unknown`, and
  // correctly so: a mapped `Record` type is not an array. Absence storage is the backend's decision
  // about its own output, so it is taken from the representation the element emitter will use -- a
  // `Record` index reads through `get`, which answers `std::optional` -- and not from a receiver name.
  //
  // The other side of the same boundary: the decision is still `nullish`-tested reads only. A read that
  // is never tested against a sentinel keeps the storage its type states, so widening the evidence did
  // not quietly make every indexed read optional.
  it('takes absence storage from the read representation and only for a nullish-tested read', () => {
    const untested = emitIrModuleCpp(
      lower(
        'record-element-untested.ts',
        `export function lookup(values: Readonly<Record<string, string>>, key: string): string {
           return values[key];
         }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    expect(untested).toContain('return values.get(key).value();');
    expect(untested).not.toContain('std::optional<flight::String>');
    expect(untested).not.toContain('.has_value()');
  });

  // The refusal this round must not trade away. `const x: any = 3` is stored as the `double` its
  // initializer proves, while every type query still reports the annotation, so the presence test has no
  // absence channel to read and declines rather than choosing between two sources that disagree. A
  // mutable `any` is a different answer and is covered above: its storage is the erased value, which
  // carries the predicate.
  it('keeps refusing a presence test whose storage and annotation disagree', () => {
    const refusal = (source: string): string | undefined => {
      try {
        emitIrModuleCpp(lower('erased-annotated-const.ts', source).module, { runtimeProfile: 'flight-cpp' });
        return undefined;
      } catch (error) {
        return isBackendEmissionFailure(error) ? error.rule : undefined;
      }
    };

    expect(refusal(`export function f(): boolean { const x: any = 3; return x !== undefined; }`)).toBe(
      'cpp-presence-test-without-absence-storage',
    );
    expect(refusal(`export function f(): boolean { const x: any = 3; return x === undefined; }`)).toBe(
      'cpp-presence-test-without-absence-storage',
    );
  });

  // The invariant the erased election exists to hold: a position the SOURCE wrote as `any` or
  // `unknown` is a value of no stated type, and flight-cpp's erased dynamic value is exactly that, so it
  // stays a number when it holds a number rather than being misstated as an object reference. Pinned
  // across the positions a written annotation can appear in, because the election is one rule and the
  // positions are what would diverge if it were moved.
  it('elects the erased dynamic value in every position the source writes an unconstrained type', () => {
    const emitted = emitIrModuleCpp(
      lower(
        'erased-positions.ts',
        `interface Holder { value: any; other: unknown }
         export function readHolder(holder: Holder): void { void holder.value; void holder.other; }
         export function readList(values: readonly unknown[]): void { void values; }
         export function readOptional(value?: unknown): void { void value; }
         export function readRecord(values: Readonly<Record<string, unknown>>): void { void values; }`,
      ).module,
      { runtimeProfile: 'flight-cpp' },
    ).contents;

    expect(emitted).toContain('#include <flight/any.hpp>');
    expect(emitted).toContain('flight::Any value;');
    expect(emitted).toContain('flight::Any other;');
    expect(emitted).toContain('flight::Array<flight::Any> values');
    expect(emitted).toContain('std::optional<flight::Any> value');
    expect(emitted).toContain('flight::Record<flight::String, flight::Any> values');
    // Nothing in a type position is left as an `auto` placeholder, which is what the guard refuses.
    expect(emitted).not.toMatch(/<[^>\n]*\bauto\b/u);
    expect(emitted).not.toMatch(/\busing\s+[A-Za-z_][A-Za-z0-9_]*\s*=\s*auto\s*;/u);
  });

